def run_days(tasks, rest):
    last = {}
    day = 0
    days = []
    for machine in tasks:
        day += 1
        while machine in last and day - last[machine] <= rest.get(machine, 0):
            day += 1
        last[machine] = day
        days.append(day)
    return days
